    private Object get(Object target,String name)throws Exception{java.lang.reflect.Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    private AccessibilityNodeInfo find(AccessibilityNodeInfo root,String text){if(root==null)return null;if(text.contentEquals(root.getText()==null?"":root.getText()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo found=find(root.getChild(i),text);if(found!=null)return found;}return null;}
    private String uiText(AccessibilityNodeInfo n){if(n==null)return "null";String value="["+n.getClassName()+":"+n.getText()+"]";for(int i=0;i<n.getChildCount();i++)value+=uiText(n.getChild(i));return value;}
    private boolean click(String text){for(int attempt=0;attempt<20;attempt++){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null)root.refresh();AccessibilityNodeInfo n=find(root,text);if(n==null){for(android.view.accessibility.AccessibilityWindowInfo window:getUiAutomation().getWindows()){n=find(window.getRoot(),text);if(n!=null)break;}}if(n!=null&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK))return true;SystemClock.sleep(250);}return false;}
    private void fields(AccessibilityNodeInfo root,List<AccessibilityNodeInfo> list){if(root==null)return;if("android.widget.EditText".contentEquals(root.getClassName()))list.add(root);for(int i=0;i<root.getChildCount();i++)fields(root.getChild(i),list);}
